SELECT ?studio ?studioLabelEn ?studioLabelRu ?performer ?performerLabelEn ?performerLabelRu ?period_start ?gold_count_estimate WHERE {
      {
        SELECT ?studio ?studioLabelEn ?studioLabelRu ?performer ?performerLabelEn ?performerLabelRu ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        ?item wdt:P31 wd:Q169930 .
        ?item wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?item wdt:P483 ?studio .
        ?item wdt:P175 ?performer .
        ?studio rdfs:label ?studioLabelEn FILTER(LANG(?studioLabelEn) = "en") .
        OPTIONAL { ?studio rdfs:label ?studioLabelRu FILTER(LANG(?studioLabelRu) = "ru") . }
        ?performer rdfs:label ?performerLabelEn FILTER(LANG(?performerLabelEn) = "en") .
        OPTIONAL { ?performer rdfs:label ?performerLabelRu FILTER(LANG(?performerLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 15) * 15 + 1950) AS ?period_start) .
        }
        GROUP BY ?studio ?studioLabelEn ?studioLabelRu ?performer ?performerLabelEn ?performerLabelRu ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800

